// Tree DP - Recursion
// At each node: combine children's results via post-order traversal
// Each node reports a state pair (included, excluded) or similar
// TIME: Exponential without caching, SPACE: O(h) recursion depth

// VARIATION 1: House Robber III (included/excluded pair)
class TreeNode {
    int val;
    TreeNode left, right;
}

public int rob(TreeNode node) {
    if (node == null) return 0;
    return node.val + skip(node.left) + skip(node.right);
}

public int skip(TreeNode node) {
    if (node == null) return 0;
    int leftBest = Math.max(rob(node.left), skip(node.left));
    int rightBest = Math.max(rob(node.right), skip(node.right));
    return leftBest + rightBest;
}

public int solve(TreeNode root) {
    return Math.max(rob(root), skip(root));
}

// VARIATION 2: Diameter (returns height, tracks diameter as side effect)
int diameter = 0;

public int height(TreeNode node) {
    if (node == null) return 0;
    int leftH = height(node.left);
    int rightH = height(node.right);
    diameter = Math.max(diameter, leftH + rightH);
    return Math.max(leftH, rightH) + 1;
}

// VARIATION 3: Max Path Sum (returns clipped downward sum)
int maxSum = Integer.MIN_VALUE;

public int maxGain(TreeNode node) {
    if (node == null) return 0;
    int leftGain = Math.max(0, maxGain(node.left));
    int rightGain = Math.max(0, maxGain(node.right));
    maxSum = Math.max(maxSum, node.val + leftGain + rightGain);
    return node.val + Math.max(leftGain, rightGain);
}

