// Tree DP - Memoization
// Cache keyed by node REFERENCE (not value)
// TIME: O(n), SPACE: O(n) memo + O(h) stack

// VARIATION 1: House Robber III
import java.util.HashMap;
import java.util.Map;

Map<TreeNode, Integer> robMemo = new HashMap<>();
Map<TreeNode, Integer> skipMemo = new HashMap<>();

public int rob(TreeNode node) {
    if (node == null) return 0;
    if (robMemo.containsKey(node)) return robMemo.get(node);
    int result = node.val + skip(node.left) + skip(node.right);
    robMemo.put(node, result);
    return result;
}

public int skip(TreeNode node) {
    if (node == null) return 0;
    if (skipMemo.containsKey(node)) return skipMemo.get(node);
    int leftBest = Math.max(rob(node.left), skip(node.left));
    int rightBest = Math.max(rob(node.right), skip(node.right));
    int result = leftBest + rightBest;
    skipMemo.put(node, result);
    return result;
}

public int solve(TreeNode root) {
    return Math.max(rob(root), skip(root));
}

// VARIATION 2: Generic pattern with pair cache
Map<TreeNode, int[]> memo = new HashMap<>();

public int[] dfs(TreeNode node) {
    if (node == null) return new int[]{0, 0};
    if (memo.containsKey(node)) return memo.get(node);

    int[] left = dfs(node.left);
    int[] right = dfs(node.right);

    int included = node.val + left[1] + right[1];
    int excluded = Math.max(left[0], left[1]) + Math.max(right[0], right[1]);

    int[] result = new int[]{included, excluded};
    memo.put(node, result);
    return result;
}

templates.tabulation:
// Tree DP - Tabulation (Post-Order, returning pair)
// Each node returns (included, excluded) computed from children
// No separate memo needed: each result used once by parent
// TIME: O(n), SPACE: O(h) recursion stack

// VARIATION 1: House Robber III (clean pair return)
public int rob(TreeNode root) {
    int[] result = solve(root);
    return Math.max(result[0], result[1]);
}

private int[] solve(TreeNode node) {
    if (node == null) return new int[]{0, 0};

    int[] left = solve(node.left);
    int[] right = solve(node.right);

    // included: take this node, children must be excluded
    int included = node.val + left[1] + right[1];

    // excluded: skip this node, each child picks its best
    int excluded = Math.max(left[0], left[1]) + Math.max(right[0], right[1]);

    return new int[]{included, excluded};
}

// VARIATION 2: Diameter (returns height, tracks answer separately)
public int diameterOfBinaryTree(TreeNode root) {
    int[] diameter = new int[1];
    height(root, diameter);
    return diameter[0];
}

private int height(TreeNode node, int[] diameter) {
    if (node == null) return 0;
    int left = height(node.left, diameter);
    int right = height(node.right, diameter);
    diameter[0] = Math.max(diameter[0], left + right);
    return Math.max(left, right) + 1;
}

// VARIATION 3: Max Path Sum
public int maxPathSum(TreeNode root) {
    int[] maxSum = new int[]{Integer.MIN_VALUE};
    maxGain(root, maxSum);
    return maxSum[0];
}

private int maxGain(TreeNode node, int[] maxSum) {
    if (node == null) return 0;
    int leftGain = Math.max(0, maxGain(node.left, maxSum));
    int rightGain = Math.max(0, maxGain(node.right, maxSum));
    maxSum[0] = Math.max(maxSum[0], node.val + leftGain + rightGain);
    return node.val + Math.max(leftGain, rightGain);
}

