class Solution {
    public int rob(TreeNode root) {
        return Math.max(robNode(root), skipNode(root));
    }

    private int robNode(TreeNode node) {
        if (node == null) return 0;
        return node.val + skipNode(node.left) + skipNode(node.right);
    }

    private int skipNode(TreeNode node) {
        if (node == null) return 0;
        int leftBest = Math.max(robNode(node.left), skipNode(node.left));
        int rightBest = Math.max(robNode(node.right), skipNode(node.right));
        return leftBest + rightBest;
    }
}

