// House Robber III - Iterative Post-Order
// TIME: O(n), SPACE: O(n)
// Use when tree is very deep/skewed and recursion may overflow

import java.util.*;

class Solution {
    public int rob(TreeNode root) {
        if (root == null) return 0;

        Map<TreeNode, int[]> dp = new HashMap<>();
        Deque<TreeNode> stack = new ArrayDeque<>();
        stack.push(root);

        while (!stack.isEmpty()) {
            TreeNode node = stack.peek();

            boolean leftDone = node.left == null || dp.containsKey(node.left);
            boolean rightDone = node.right == null || dp.containsKey(node.right);

            if (leftDone && rightDone) {
                stack.pop();
                int[] left = dp.getOrDefault(node.left, new int[]{0, 0});
                int[] right = dp.getOrDefault(node.right, new int[]{0, 0});

                int included = node.val + left[1] + right[1];
                int excluded = Math.max(left[0], left[1]) + Math.max(right[0], right[1]);
                dp.put(node, new int[]{included, excluded});
            } else {
                if (node.right != null && !dp.containsKey(node.right)) {
                    stack.push(node.right);
                }
                if (node.left != null && !dp.containsKey(node.left)) {
                    stack.push(node.left);
                }
            }
        }

        int[] result = dp.get(root);
        return Math.max(result[0], result[1]);
    }
}

