// TIME: O(n), SPACE: O(n)
// Use when tree is very deep/skewed and recursion may overflow

function rob(root) {
    if (root === null) return 0;

    const dp = new Map();
    const stack = [root];

    while (stack.length > 0) {
        const node = stack[stack.length - 1];

        const leftDone = node.left === null || dp.has(node.left);
        const rightDone = node.right === null || dp.has(node.right);

        if (leftDone && rightDone) {
            stack.pop();
            const left = dp.get(node.left) || [0, 0];
            const right = dp.get(node.right) || [0, 0];

            const included = node.val + left[1] + right[1];
            const excluded = Math.max(left[0], left[1]) + Math.max(right[0], right[1]);
            dp.set(node, [included, excluded]);
        } else {
            if (node.right !== null && !dp.has(node.right)) {
                stack.push(node.right);
            }
            if (node.left !== null && !dp.has(node.left)) {
                stack.push(node.left);
            }
        }
    }

    const result = dp.get(root);
    return Math.max(result[0], result[1]);
}
